import math
from itertools import combinations_with_replacement

D = [1, 7, 11, 13, 77, 91, 143, 1001]
N = 1001

def calculate_K(a, b, c):
    # K = sqrt(1001/a) + sqrt(1001/b) + sqrt(1001/c)
    try:
        K = math.sqrt(N / a) + math.sqrt(N / b) + math.sqrt(N / c)
        return K
    except ZeroDivisionError:
        return None

print("Testing combinations (a, b, c) such that a <= b <= c:")
solutions_found = []
for combo in combinations_with_replacement(D, 3):
    a, b, c = combo
    K_val = calculate_K(a, b, c)

    # Check if K is close to an integer
    if K_val is not None:
        K_rounded = round(K_val)
        if abs(K_val - K_rounded) < 1e-9:
            solutions_found.append(combo)
            print(f"Integer solution found: {combo}, K = {K_rounded}")

if not solutions_found:
    print("No integer solutions found in reduced forms.")
else:
    print(f"Total reduced solutions found: {len(solutions_found)}")

